test.fill_query:
INSERT INTO string_size_read_planning_{serialization}
SELECT number, repeat('x', number % 32)
FROM numbers(4096)

test.query:
SELECT s, s.size FROM string_size_read_planning_{serialization}
PREWHERE s.size > 0 AND id % 3 != 0 AND position(s, 'x') = 1
    AND s.size + id > 0 FORMAT Null

SELECT s, s.size FROM string_size_read_planning_{serialization}
PREWHERE s.size + position(s, 'x') > 0 AND id % 3 != 0
    AND s.size + id > 1 FORMAT Null

SELECT s, s.size FROM string_size_read_planning_{serialization}
PREWHERE s.size > 0 AND id % 3 != 0
    AND s.size + position(s, 'x') > 1 FORMAT Null
